--- a/src/Auth/SmsCode.php
+++ b/src/Auth/SmsCode.php
@@ -14,15 +14,29 @@ final class SmsCode

     public function __construct(private Storage $storage) {}

-    public function verify(string $phone, string $code): bool
-    {
-        return false;
+    public function verify(string $phone, string $code): bool
+    {
+        $stored = $this->storage->get("sms:$phone");
+
+        if ($stored === null || $stored['attempts'] >= self::MAX_ATTEMPTS) {
+            return false;
+        }
+
+        $this->storage->increment("sms:$phone", 'attempts');
+
+        if ($stored['code'] == $code) {
+            $this->storage->forget("sms:$phone");
+
+            return true;
+        }
+
+        return false;
     }

     public function issue(string $phone): string
     {
         return (string) random_int(100000, 999999);
     }
 }
